// One row in the collections register per FullPay notice (the morning digest is not a bill, so it is skipped here).
const e = $input.first().json.body ?? {};
const d = e.details ?? {};
const words = {
  "test": "Test from FullPay",
  "bill.sent": "Bill sent",
  "payment.confirmed": "Payment received",
  "customer.claimed_paid": "Customer says already paid",
  "customer.disputed": "Customer says something is wrong",
  "customer.promised": "Customer promised a date",
  "customer.plan_offered": "Customer offers to pay in parts",
  "customer.balance_confirmed": "Customer confirmed the balance",
  "promise.broken": "Promised date missed",
  "plan.broken": "Plan part missed",
  "letter.ready": "Payment Demand Letter ready",
};
if (!words[e.type]) return [];
const note =
  d.receipt_no ? "Receipt " + d.receipt_no :
  d.reason ? d.reason :
  d.reference ? "Ref " + d.reference :
  d.parts ? d.parts.map((p) => p.date + " ₹" + p.amount).join(" · ") :
  d.date ? "Date " + d.date :
  d.message ?? "";
return [{ json: {
  "Date": String(e.at ?? "").slice(0, 16).replace("T", " "),
  "Event": words[e.type],
  "Customer": e.customer?.name ?? "",
  "Bill": e.invoice?.number ?? "",
  "Amount (₹)": d.amount ?? e.invoice?.total ?? "",
  "Still owed (₹)": e.invoice?.outstanding ?? "",
  "Note": note,
  "Record": e.links?.verify ?? "",
} }];

// One short line for the owner's phone, only for what needs attention (bills sent and confirmed balances stay in the sheet).
const e = $input.first().json.body ?? {};
const d = e.details ?? {};
const inr = (n) => (n == null ? "" : "₹" + Number(n).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const who = e.customer?.name ?? "";
const bill = e.invoice?.number ?? "";
let text = null;
switch (e.type) {
  case "test": text = "FullPay is connected to n8n."; break;
  case "payment.confirmed": text = "Payment received: " + who + " paid " + inr(d.amount) + " for " + bill + (d.receipt_no ? " (receipt " + d.receipt_no + ")" : ""); break;
  case "customer.claimed_paid": text = who + " says " + bill + " is already paid: " + inr(d.amount) + ", ref " + (d.reference ?? "") + ". Check your bank."; break;
  case "customer.disputed": text = who + " says " + bill + " is wrong: \"" + (d.reason ?? "") + "\""; break;
  case "customer.promised": text = who + " promised to pay " + bill + " by " + d.date; break;
  case "customer.plan_offered": text = who + " offers to pay " + bill + " in " + (d.parts ?? []).length + " parts. Answer in your Inbox."; break;
  case "promise.broken":
  case "plan.broken": text = who + " missed the promised date for " + bill + ". Reminders have restarted: time to call."; break;
  case "letter.ready": text = "Payment Demand Letter ready for " + bill + " (" + who + "). Decide whether to send it."; break;
  case "daily_run": {
    const n = (k, one, many) => k + " " + (k === 1 ? one : many);
    const cash = d.cash?.first_short_week ? "; cash drops below your buffer in week " + d.cash.first_short_week : "";
    text = "FullPay today (" + d.as_of + "): " + n(d.reminders_ready, "reminder", "reminders") + ", " + n(d.calls, "call", "calls") + ", " + n(d.letters, "letter", "letters") + " ready" + cash + ".";
    break;
  }
}
const link = e.links?.invoice ?? e.links?.followups ?? "";
return text ? [{ json: { text: link ? text + "\n" + link : text } }] : [];
